const dir = 'C:\\Users\\刘子韬\\Documents\\deepseek-harness\\default-workspace\\AI-学习';
const scriptPath = dir + '\\tools\\list-notes.ps1';

const writer = await agent(`你是一名严谨的工程师。请创建一个 PowerShell 脚本，路径必须精确为：
${scriptPath}

脚本要求：
1. 扫描目录 ${dir} 下的所有 .md 文件（不递归子目录）。
2. 输出一张表，列依次为：Name、Bytes、Lines、Chars（Chars 为该文件 UTF-8 字符数）。
3. 按 Bytes 降序排列。
4. 目标目录不存在时，往 stderr 报错并以退出码 1 结束。
5. 文件名可能含中文和空格，必须正确处理。

工作纪律：
- 必须自己用 pwsh 实际运行该脚本，确认输出正确、无报错、无乱码。
- 只创建/修改这一个脚本文件，不要动其他任何文件。

完成后返回 path（脚本绝对路径）与 what（一句话说明你实际验证了什么）。`, {
  label: 'A 写脚本并自测',
  phase: '生成',
  schema: {
    type: 'object',
    properties: { path: { type: 'string' }, what: { type: 'string' } },
    required: ['path', 'what'],
    additionalProperties: false,
  },
});

phase('独立验证');

const reviewer = await agent(`你是一名独立的敌对代码审查者。你要审查的脚本在：
${scriptPath}

审查规则（必须严格遵守）：
1. 不要相信任何人的说法，包括上一位作者。自己读取脚本内容，自己运行它。
2. 用 Get-ChildItem / Get-Content 独立测量每个 .md 文件的真实字节数、行数、字符数，与脚本输出逐项比对，误差即为缺陷。
3. 主动测试边界情况：文件名含中文与空格、目录内容变化、目标目录不存在时的错误处理与退出码。
4. 重点检查：列名是否正确（Name/Bytes/Lines/Chars）、排序是否真的按 Bytes 降序、统计口径是否准确（尤其字符数是否把多字节字符算对）、是否只列了 .md。
5. 只要发现任何一处与要求不符，verdict 必须是 FAIL 并列出具体问题；全部通过才可 PASS。

返回 verdict（PASS 或 FAIL）、problems（字符串数组，通过则为空数组）、evidence（你实际运行的关键命令与输出摘要）。`, {
  label: 'B 独立审查并运行验证',
  phase: '独立验证',
  schema: {
    type: 'object',
    properties: {
      verdict: { type: 'string', enum: ['PASS', 'FAIL'] },
      problems: { type: 'array', items: { type: 'string' } },
      evidence: { type: 'string' },
    },
    required: ['verdict', 'problems', 'evidence'],
    additionalProperties: false,
  },
});

return { writer, reviewer, round: 1 };"}

