  --success: #0f9d6e;
  --success-bg: #e8f8f1;
  --warn: #c47d0a;
  --warn-bg: #fdf4e3;
  --danger: #d83a3a;
  --danger-bg: #fdecec;

  --radius-sm: 8px;
  --radius: 14px;
  --radius-lg: 20px;

  --shadow-sm: 0 1px 2px rgba(20, 22, 31, 0.04), 0 1px 3px rgba(20, 22, 31, 0.03);
  --shadow: 0 4px 16px rgba(20, 22, 31, 0.06), 0 1px 3px rgba(20, 22, 31, 0.04);
  --shadow-lg: 0 18px 48px rgba(20, 22, 31, 0.12);

  --font-sans: 'Inter', -apple-system, 'Segoe UI', 'Microsoft YaHei', sans-serif;
  --font-serif: 'Noto Serif SC', 'Songti SC', 'SimSun', serif;
  --font-mono: 'JetBrains Mono', 'Cascadia Code', Consolas, monospace;
}

