  color: var(--danger);
}

/* ── 首页 ─────────────────────────────────────────────────── */
.hero {
  position: relative;
  overflow: hidden;
  border-radius: var(--radius-lg);
  padding: 34px 36px;
  background: radial-gradient(120% 140% at 0% 0%, #3b3fbf 0%, #4f46e5 42%, #7c6cf5 100%);
  color: #fff;
  margin-bottom: 22px;
  box-shadow: 0 18px 44px rgba(59, 63, 191, 0.3);
