  width: 320px;
  height: 320px;
  border-radius: 50%;
  background: radial-gradient(circle, rgba(255, 255, 255, 0.22), transparent 65%);
}

.hero h1 {
  font-family: var(--font-serif);
  font-size: 30px;
  margin: 0 0 10px;
  letter-spacing: 1px;
}

.hero p {
  margin: 0;
  max-width: 590px;
  color: rgba(255, 255, 255, 0.86);
  font-size: 13.5px;
  line-height: 1.8;
}

.hero-actions {
  display: flex;
  gap: 12px;
