{"content": "// Spike: can we drive headless Edge via CDP and capture frames?
import { spawn } from 'node:child_process'
import fs from 'node:fs'
import path from 'node:path'

const EDGE = 'C:\\Program Files (x86)\\Microsoft\\Edge\\Application\\msedge.exe'
const TMP_PROFILE = path.join(process.env.TEMP, 'edge-cdp-profile')
const PORT = 9333

const child = spawn(EDGE, [
  '--headless=new',
  '--disable-gpu',
  '--hide-scrollbars',
  '--window-size=1920,1080',
  `--remote-debugging-port=${PORT}`,
  `--user-data-dir=${TMP_PROFILE}`,
  'about:blank',
], { stdio: 'ignore', detached: false })

const sleep = (ms) => new Promise((r) => setTimeout(r, ms))

async function getJson(url) {
  const res = await fetch(url)
  return res.json()
}

async function main() {
  // wait for devtools
  let targets = null
  for (let i = 0; i < 40; i += 1) {
    try {
      targets = await getJson(`http://127.0.0.1:${PORT}/json`)
      if (targets.length) break
    } catch {
      /* retry */
    }
    await sleep(250)
  }
  if (!targets) throw new Error('devtools not reachable')
  console.log('targets:', targets.map((t) => t.type + ' ' + t.url))

  const page = targets.find((t) => t.type === 'page')
  const ws = new WebSocket(page.webSocketDebuggerUrl)
  let id = 0
  const pending = new Map()

  const send = (method, params = {}) =>
    new Promise((resolve, reject) => {
      const msgId = ++id
      pending.set(msgId, { resolve, reject })
      ws.send(JSON.stringify({ id: msgId, method, params }))
    })

  const frames = []
  ws.addEventListener('message', (event) => {
    const msg = JSON.parse(event.data)
    if (msg.id && pending.has(msg.id)) {
      const { resolve, reject } = pending.get(msg.id)
      pending.delete(msg.id)
      if (msg.error) reject(new Error(JSON.stringify(msg.error)))
      else resolve(msg.result)
      return
    }
    if (msg.method === 'Page.screencastFrame') {
      frames.push({ ts: msg.params.metadata.timestamp, data: msg.params.data })
      send('Page.screencastFrameAck', { sessionId: msg.params.sessionId }).catch(() => {})
    }
  })

  await new Promise((resolve) => ws.addEventListener('open', resolve))
  console.log('ws open')

  await send('Page.enable')
  await send('Runtime.enable')
  await send('Emulation.setDeviceMetricsOverride', {
    width: 1920,
    height: 1080,
    deviceScaleFactor: 1,
    mobile: false,
  })
  await send('Page.startScreencast', {
    format: 'jpeg',
    quality: 80,
    maxWidth: 1920,
    maxHeight: 1080,
    everyNthFrame: 1,
  })

  await send('Page.navigate', { url: 'http://localhost:5173/' })
  await sleep(4000)

  const title = await send('Runtime.evaluate', {
    expression: 'document.title + " | " + document.querySelectorAll(".card").length',
    returnByValue: true,
  })
  console.log('page check:', title.result.value)

  await sleep(2000)
  await send('Page.stopScreencast')

  console.log('frames captured:', frames.length)
  fs.mkdirSync('./.tmp-spike', { recursive: true })
  if (frames.length) {
    fs.writeFileSync('./.tmp-spike/f0.jpg', Buffer.from(frames[0].data, 'base64'))
    fs.writeFileSync('./.tmp-spike/f-last.jpg', Buffer.from(frames.at(-1).data, 'base64'))
    console.log('first ts', frames[0].ts, 'last ts', frames.at(-1).ts)
  }

  ws.close()
  try { child.kill() } catch { /* ignore */ }
}

main().catch((error) => {
  console.error('SPIKE FAILED:', error.message)
  try { child.kill() } catch { /* ignore */ }
  process.exit(1)
})
