{"content": "// 由真实数据生成视频所需的静态页面：
//   ai-history.html  —— 把导出的 AI 会话记录渲染成可滚动的页面
//   evidence.html    —— git 提交历史与技术栈证据页
import fs from 'node:fs'
import path from 'node:path'
import { execSync } from 'node:child_process'

const DEMO_DIR = path.dirname(new URL(import.meta.url).pathname).replace(/^\//, '')
const OUT_DIR = DEMO_DIR
const REPO = path.resolve(DEMO_DIR, '..', '..', 'zhijuan')

function escapeHtml(text) {
  return String(text)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
}

function inline(text) {
  return escapeHtml(text)
    .replace(/\*\*(.+?)\*\*/g, '<strong>$1</strong>')
    .replace(/`([^`]+)`/g, '<code>$1</code>')
    .replace(/\$([^$]+)\$/g, '<span class="math">$1</span>')
}

// 极简 Markdown → HTML（只覆盖会话记录里实际出现的语法）
function markdownToHtml(markdown) {
  const lines = markdown.split('\n')
  const out = []
  let inCode = false
  let paragraph = []

  const flush = () => {
    if (paragraph.length) {
      out.push(`<p>${paragraph.map(inline).join('<br>')}</p>`)
      paragraph = []
    }
  }

  for (const raw of lines) {
    const line = raw.replace(/\r$/, '')
    if (line.trim().startsWith('```')) {
      if (inCode) {
        out.push('</pre>')
        inCode = false
      } else {
        flush()
        out.push('<pre>')
        inCode = true
      }
      continue
    }
    if (inCode) {
      out.push(escapeHtml(line))
      continue
    }
    if (!line.trim()) {
      flush()
      continue
    }
    const heading = line.match(/^(#{1,4})\s+(.*)$/)
    if (heading) {
      flush()
      const level = Math.min(heading[1].length + 1, 5)
      out.push(`<h${level}>${inline(heading[2])}</h${level}>`)
      continue
    }
    if (line.startsWith('>')) {
      flush()
      out.push(`<blockquote>${inline(line.replace(/^>\s?/, ''))}</blockquote>`)
      continue
    }
    if (/^\|/.test(line)) {
      // 表格降级为单行文本，避免渲染错位
      const cells = line.split('|').filter((cell) => cell.trim())
      if (cells.every((cell) => /^[\s:-]+$/.test(cell))) continue
      out.push(`<p class="table-row">${cells.map(inline).join(' · ')}</p>`)
      continue
    }
    if (/^[-*]\s+/.test(line)) {
      flush()
      out.push(`<li>${inline(line.replace(/^[-*]\s+/, ''))}</li>`)
      continue
    }
    paragraph.push(line)
  }
  flush()
  if (inCode) out.push('</pre>')
  return out.join('\n')
}

const PAGE_CSS = `
  * { box-sizing: border-box; }
  body {
