// ── CDP 客户端 ───────────────────────────────────────────────────────
class Cdp {
  constructor(ws) {
    this.ws = ws
    this.id = 0
    this.pending = new Map()
    this.frames = []
    ws.addEventListener('message', (event) => {
      const msg = JSON.parse(event.data)
      if (msg.id && this.pending.has(msg.id)) {
        const { resolve, reject } = this.pending.get(msg.id)
        this.pending.delete(msg.id)
        if (msg.error) reject(new Error(JSON.stringify(msg.error)))
        else resolve(msg.result)
        return
      }
      if (msg.method === 'Page.screencastFrame') {
        this.frames.push({ ts: msg.params.metadata.timestamp, data: msg.params.data })
        this.send('Page.screencastFrameAck', { sessionId: msg.params.sessionId }).catch(() => {})
      }
    })
  }

  send(method, params = {}) {
    return new Promise((resolve, reject) => {
      const msgId = ++this.id
      this.pending.set(msgId, { resolve, reject })
      this.ws.send(JSON.stringify({ id: msgId, method, params }))
    })
  }

  async evaluate(expression, returnByValue = true) {
    const result = await this.send('Runtime.evaluate', {
      expression,
      returnByValue,
      awaitPromise: true,
    })
    if (result.exceptionDetails) throw new Error(result.exceptionDetails.text)
    return result.result?.value
  }

  async goto(url) {
    await this.send('Page.navigate', { url })
    await sleep(1200)
  }

  async scroll(deltaY, stepMs = 500) {
    await this.evaluate(`window.scrollBy({top: ${deltaY}, behavior: 'smooth'})`)
    await sleep(stepMs)
  }

  async clickByText(selector, text) {
    const ok = await this.evaluate(
      `(() => {
        const nodes = [...document.querySelectorAll(${JSON.stringify(selector)})];
        const hit = nodes.find((n) => n.textContent.replace(/\\s+/g, '').includes(${JSON.stringify(text)}));
        if (!hit) return false;
        hit.click();
        return true;
      })()`,
    )
    if (!ok) throw new Error(`未找到可点击元素：${selector} 含「${text}」`)
    await sleep(400)
  }

  async setValue(selector, value) {
    const ok = await this.evaluate(
      `(() => {
        const el = document.querySelector(${JSON.stringify(selector)});
        if (!el) return false;
        const proto = el instanceof HTMLTextAreaElement ? HTMLTextAreaElement.prototype : HTMLInputElement.prototype;
        const setter = Object.getOwnPropertyDescriptor(proto, 'value').set;
        setter.call(el, ${JSON.stringify(value)});
        el.dispatchEvent(new Event('input', { bubbles: true }));
        el.dispatchEvent(new Event('change', { bubbles: true }));
        return true;
      })()`,
    )
    if (!ok) throw new Error(`未找到输入框：${selector}`)
    await sleep(300)
  }

  async setNumberInput(index, value) {
    await this.evaluate(
      `(() => {
        const inputs = [...document.querySelectorAll('input[type="number"]')];
        const el = inputs[${index}];
        if (!el) return false;
        const setter = Object.getOwnPropertyDescriptor(HTMLInputElement.prototype, 'value').set;
        setter.call(el, '${value}');
        el.dispatchEvent(new Event('input', { bubbles: true }));
        el.dispatchEvent(new Event('change', { bubbles: true }));
        return true;
      })()`,
    )
    await sleep(200)
  }

  async waitFor(expression, timeoutMs = 120000, interval = 500) {
    const started = Date.now()
    while (Date.now() - started < timeoutMs) {
      const ok = await this.evaluate(expression).catch(() => false)
      if (ok) return true
      await sleep(interval)
    }
    throw new Error(`等待超时：${expression}`)
  }
}

async function launch() {
  const profile = path.join(process.env.TEMP, 'edge-demo-profile')
  const child = spawn(
    EDGE,
    [
      '--headless=new',
      '--disable-gpu',
      '--hide-scrollbars',
      '--mute-audio',
      '--window-size=1920,1080',
      `--remote-debugging-port=${PORT}`,
      `--user-data-dir=${profile}`,
      'about:blank',
    ],
    { stdio: 'ignore' },
  )

  let targets = null
  for (let i = 0; i < 60; i += 1) {
    try {
      const res = await fetch(`http://127.0.0.1:${PORT}/json`)
      targets = await res.json()
      if (targets.some((t) => t.type === 'page')) break
    } catch {
      /* retry */
    }
    await sleep(300)
  }
  const page = targets?.find((t) => t.type === 'page')
  if (!page) throw new Error('无法连接 Edge 调试端口')

  const ws = new WebSocket(page.webSocketDebuggerUrl)
  await new Promise((resolve) => ws.addEventListener('open', resolve))
  const cdp = new Cdp(ws)

  await cdp.send('Page.enable')
  await cdp.send('Runtime.enable')
  await cdp.send('Emulation.setDeviceMetricsOverride', {
    width: 1920,
    height: 1080,
    deviceScaleFactor: 1,
    mobile: false,
  })

  return { child, cdp, ws }
}

async function recordSegment(cdp, segment) {
  const dir = path.join(OUT_ROOT, segment.id)
  fs.rmSync(dir, { recursive: true, force: true })
  fs.mkdirSync(path.join(dir, 'frames'), { recursive: true })

  cdp.frames = []
  await cdp.send('Page.startScreencast', {
    format: 'jpeg',
    quality: 82,
    maxWidth: 1920,
    maxHeight: 1080,
    everyNthFrame: 1,
  })

  const started = Date.now()
  try {
    await segment.actions(new Ctx(cdp))
  } catch (error) {
    console.error(`  ! ${segment.id} 动作异常：${error.message}`)
  }

  await sleep(600)
  await cdp.send('Page.stopScreencast')
  const elapsed = (Date.now() - started) / 1000

  // 保存帧并计算每帧显示时长
  const frames = cdp.frames
  if (frames.length === 0) throw new Error(`${segment.id} 没有捕获到任何帧`)
  const base = frames[0].ts
  let prev = 0
  const timeline = []
  frames.forEach((frame, index) => {
    const rel = frame.ts - base
    timeline.push({ index, at: Number(rel.toFixed(3)) })
    const file = path.join(dir, 'frames', `${String(index).padStart(5, '0')}.jpg`)
    fs.writeFileSync(file, Buffer.from(frame.data, 'base64'))
    prev = rel
  })

  const meta = {
    id: segment.id,
    elapsed,
    frameCount: frames.length,
    capturedUntil: Number(prev.toFixed(3)),
    timeline,
  }
  fs.writeFileSync(path.join(dir, 'meta.json'), JSON.stringify(meta, null, 2), 'utf8')
  fs.writeFileSync(path.join(dir, 'narration.txt'), segment.narration, 'utf8')

  console.log(
    `  ${segment.id}: ${frames.length} 帧 / 录制 ${elapsed.toFixed(1)}s / 画面跨度 ${prev.toFixed(1)}s`,
  )
  return meta
}

class Ctx {
  constructor(cdp) {
    this.cdp = cdp
  }
  evaluate(...args) {
    return this.cdp.evaluate(...args)
  }
  goto(...args) {
    return this.cdp.goto(...args)
  }
  scroll(...args) {
    return this.cdp.scroll(...args)
  }
  clickByText(...args) {
    return this.cdp.clickByText(...args)
  }
  setValue(...args) {
    return this.cdp.setValue(...args)
  }
  setNumberInput(...args) {
    return this.cdp.setNumberInput(...args)
  }
  waitFor(...args) {
    return this.cdp.waitFor(...args)
  }
}

async function main() {
  const only = process.argv.slice(2)
  const list = only.length ? SEGMENTS.filter((s) => only.includes(s.id)) : SEGMENTS

  fs.mkdirSync(OUT_ROOT, { recursive: true })
  const { child, cdp, ws } = await launch()
  console.log('浏览器已连接，开始录制分段…')

  for (const segment of list) {
    console.log(`▶ ${segment.id}`)
    await recordSegment(cdp, segment)
  }

  ws.close()
  try {
    child.kill()
  } catch {
    /* ignore */
  }
  console.log('全部录制完成')
}

main().catch((error) => {
  console.error('录制失败：', error.message)
  process.exit(1)
})
