{"content": "# Generate narration WAV files for each recorded segment using Windows SAPI (Huihui zh-CN).
$ErrorActionPreference = "Continue"
$tools = Split-Path -Parent $MyInvocation.MyCommand.Path
$demo = Join-Path $tools "demo"
$outRoot = Join-Path $demo "out"

Add-Type -AssemblyName System.Speech

$dirs = Get-ChildItem $outRoot -Directory -Filter "s*" | Sort-Object Name
if ($dirs.Count -eq 0) {
  Write-Host "no segment folders found"
  exit 1
}

foreach ($dir in $dirs) {
  $textFile = Join-Path $dir.FullName "narration.txt"
  if (-not (Test-Path $textFile)) { continue }
  $text = (Get-Content $textFile -Raw -Encoding UTF8).Trim()
  if (-not $text) { continue }

  $wav = Join-Path $dir.FullName "narration.wav"
  $synth = New-Object System.Speech.Synthesis.SpeechSynthesizer
  try {
    $synth.SelectVoice("Microsoft Huihui Desktop")
  } catch {
    Write-Host "  (Huihui not available, using default voice)"
  }
  # 语速略慢，便于听清
  $synth.Rate = -1
  $synth.Volume = 100
  $format = New-Object System.Speech.AudioFormat.SpeechAudioFormatInfo(
    44100,
    [System.Speech.AudioFormat.AudioBitsPerSample]::Sixteen,
    [System.Speech.AudioFormat.AudioChannel]::Mono
  )
  $synth.SetOutputToWaveFile($wav, $format)
  $synth.Speak($text)
  $synth.Dispose()

  $info = Get-Item $wav
  Write-Host ("  {0}: {1} chars -> {2} KB" -f $dir.Name, $text.Length, [math]::Round($info.Length / 1KB, 0))
}

Write-Host "TTS done"
