{"content": "// 把录制好的帧序列 + TTS 旁白合成为 1080p 演示视频。
//
//   node tools/demo/assemble.mjs
import { spawnSync } from 'node:child_process'
import fs from 'node:fs'
import path from 'node:path'
import { fileURLToPath } from 'node:url'

const DEMO_DIR = path.dirname(fileURLToPath(import.meta.url))
const TOOLS_DIR = path.resolve(DEMO_DIR, '..')
const FFMPEG = path.join(TOOLS_DIR, 'ffmpeg.exe')
const OUT_ROOT = path.join(DEMO_DIR, 'out')
const FINAL = path.join(OUT_ROOT, '最终成片.mp4')

function run(args, label) {
  const result = spawnSync(FFMPEG, args, { encoding: 'utf8' })
  if (result.status !== 0) {
    console.error(`ffmpeg 失败（${label}）：`)
    console.error((result.stderr || '').split('\n').slice(-14).join('\n'))
    throw new Error(`ffmpeg failed: ${label}`)
  }
  return result.stderr || ''
}

function probeDuration(file) {
  const output = run(['-hide_banner', '-i', file], 'probe')
  const match = output.match(/Duration:\s*(\d+):(\d+):(\d+(?:\.\d+)?)/)
  if (!match) return 0
  return Number(match[1]) * 3600 + Number(match[2]) * 60 + Number(match[3])
}

function buildSegment(dir) {
  const metaPath = path.join(dir, 'meta.json')
  const wav = path.join(dir, 'narration.wav')
  if (!fs.existsSync(metaPath)) return null
  if (!fs.existsSync(wav)) {
    console.warn(`  ! ${path.basename(dir)} 缺少 narration.wav，跳过`)
    return null
  }

  const meta = JSON.parse(fs.readFileSync(metaPath, 'utf8'))
  const audioDur = probeDuration(wav)
  const timeline = meta.timeline ?? []
  if (timeline.length === 0) return null

  const frameDir = path.join(dir, 'frames')
  const frames = fs.readdirSync(frameDir).filter((f) => f.endsWith('.jpg')).sort()
  if (frames.length !== timeline.length) {
    console.warn(`  ! ${path.basename(dir)} 帧数(${frames.length})与时间线(${timeline.length})不一致，按较小值处理`)
  }

  // 每帧显示时长 = 下一帧时间 - 当前帧时间；最后一帧补齐到旁白结束
  const lines = []
  const count = Math.min(frames.length, timeline.length)
  for (let i = 0; i < count; i += 1) {
    const start = timeline[i].at
    const next = i + 1 < count ? timeline[i + 1].at : audioDur
    let duration = next - start
    if (!Number.isFinite(duration) || duration <= 0) duration = 0.04
    duration = Math.min(Math.max(duration, 0.033), 30)
    lines.push(`file '${path.join(frameDir, frames[i]).replace(/\\/g, '/')}'`)
    lines.push(`duration ${duration.toFixed(3)}`)
  }
  // concat demuxer 要求最后一张重复一次
  lines.push(`file '${path.join(frameDir, frames[count - 1]).replace(/\\/g, '/')}'`)

  const listFile = path.join(dir, 'frames.txt')
  fs.writeFileSync(listFile, lines.join('\n'), 'utf8')

  const silentVideo = path.join(dir, 'video-silent.mp4')
  run(
    [
      '-y', '-hide_banner', '-loglevel', 'error',
      '-f', 'concat', '-safe', '0', '-i', listFile,
      '-vf', 'fps=30,scale=1920:1080:force_original_aspect_ratio=decrease,pad=1920:1080:(ow-iw)/2:(oh-ih)/2:color=black,format=yuv420p',
      '-t', audioDur.toFixed(3),
      '-c:v', 'libx264', '-preset', 'veryfast', '-crf', '21',
      silentVideo,
    ],
    `${path.basename(dir)} 画面`,
  )

  const withAudio = path.join(dir, 'segment.mp4')
  run(
    [
      '-y', '-hide_banner', '-loglevel', 'error',
      '-i', silentVideo,
      '-i', wav,
      '-af', 'adelay=350|350,apad=pad_dur=0.4',
      '-c:v', 'copy', '-c:a', 'aac', '-b:a', '160k', '-ar', '44100',
      '-shortest',
      withAudio,
    ],
    `${path.basename(dir)} 合成`,
  )

  const finalDur = probeDuration(withAudio)
  console.log(
    `  ${path.basename(dir)}: 旁白 ${audioDur.toFixed(1)}s / 成段 ${finalDur.toFixed(1)}s / ${count} 帧`,
  )
  return withAudio
}

function main() {
  if (!fs.existsSync(FFMPEG)) throw new Error(`找不到 ffmpeg：${FFMPEG}`)

  const segments = fs
    .readdirSync(OUT_ROOT)
    .filter((name) => /^s\d+$/.test(name))
    .sort((a, b) => Number(a.slice(1)) - Number(b.slice(1)))
    .map((name) => path.join(OUT_ROOT, name))

  console.log(`共 ${segments.length} 个分段`)
  const produced = []
  for (const dir of segments) {
    if (!fs.existsSync(dir)) continue
    const file = buildSegment(dir)
    if (file) produced.push(file)
  }

  if (produced.length === 0) throw new Error('没有可合成的分段')

  const listFile = path.join(OUT_ROOT, 'segments.txt')
  fs.writeFileSync(
    listFile,
    produced.map((file) => `file '${file.replace(/\\/g, '/')}'`).join('\n'),
    'utf8',
  )

  run(
    ['-y', '-hide_banner', '-loglevel', 'error', '-f', 'concat', '-safe', '0', '-i', listFile, '-c', 'copy', FINAL],
    '最终拼接',
  )

  const duration = probeDuration(FINAL)
  const sizeMb = (fs.statSync(FINAL).size / 1024 / 1024).toFixed(1)
  console.log('')
  console.log(`✓ 成片：${FINAL}`)
  console.log(`  时长 ${Math.floor(duration / 60)} 分 ${Math.round(duration % 60)} 秒 · ${sizeMb} MB`)
  if (duration < 300 || duration > 480) {
    console.warn('  ⚠ 时长不在 5–8 分钟区间，需要调整旁白长度或语速')
  }
}

