const TARGET = path.join(OUT_ROOT, '最终成片-带字幕.mp4')
const SRT = path.join(OUT_ROOT, 'subtitles.srt')

const FONT_SIZE = 16
const STYLE = [
  'FontName=Microsoft YaHei',
  `FontSize=${FONT_SIZE}`,
  'PrimaryColour=&H00FFFFFF',
  'OutlineColour=&H00000000',
  'BackColour=&H66000000',
  'BorderStyle=1',
  'Outline=1.2',
  'Shadow=0',
  'MarginV=30',
  'Alignment=2',
].join(',')

function probeDuration(file) {
  const result = spawnSync(FFMPEG, ['-hide_banner', '-i', file], { encoding: 'utf8' })
  const output = `${result.stderr ?? ''}`
  const match = output.match(/Duration:\s*(\d+):(\d+):(\d+(?:\.\d+)?)/)
  if (!match) return 0
  return Number(match[1]) * 3600 + Number(match[2]) * 60 + Number(match[3])
}

// 把一段旁白切成适合单行显示的短句
function splitCaptions(text) {
  const pieces = text
    .replace(/\s+/g, '')
    .split(/(?<=[。！？；])|(?<=[，、])/)
    .filter(Boolean)

  const captions = []
  let buffer = ''
  for (const piece of pieces) {
    if (buffer.length + piece.length <= 22) {
      buffer += piece
      continue
    }
    if (buffer) captions.push(buffer)
    buffer = piece
    // 单句过长时按 22 字硬切
    while (buffer.length > 34) {
      captions.push(buffer.slice(0, 22))
      buffer = buffer.slice(22)
    }
  }
  if (buffer) captions.push(buffer)
  return captions.filter((caption) => caption.trim().length > 0)
}

function formatTime(seconds) {
  const total = Math.max(0, seconds)
  const hh = Math.floor(total / 3600)
  const mm = Math.floor((total % 3600) / 60)
  const ss = Math.floor(total % 60)
  const ms = Math.round((total - Math.floor(total)) * 1000)
  const pad = (value, size = 2) => String(value).padStart(size, '0')
  return `${pad(hh)}:${pad(mm)}:${pad(ss)},${pad(ms, 3)}`
}

function main() {
  if (!fs.existsSync(SOURCE)) throw new Error(`找不到成片：${SOURCE}`)

  const dirs = fs
    .readdirSync(OUT_ROOT)
    .filter((name) => /^s\d+$/.test(name))
    .sort((a, b) => Number(a.slice(1)) - Number(b.slice(1)))

  const entries = []
  let cursor = 0

  for (const name of dirs) {
    const dir = path.join(OUT_ROOT, name)
    const segmentMp4 = path.join(dir, 'segment.mp4')
    const narrationFile = path.join(dir, 'narration.txt')
    if (!fs.existsSync(segmentMp4) || !fs.existsSync(narrationFile)) continue

    const duration = probeDuration(segmentMp4)
    const narration = fs.readFileSync(narrationFile, 'utf8').trim()
    if (narration) {
      const captions = splitCaptions(narration)
      const totalChars = captions.reduce((sum, caption) => sum + caption.length, 0) || 1
      // 预留 0.6s 收尾，避免字幕压着画面切换
      const usable = Math.max(1, duration - 0.6)
      let offset = cursor
      for (const caption of captions) {
        const span = (caption.length / totalChars) * usable
        const start = offset
        const end = Math.min(cursor + duration - 0.2, offset + Math.max(0.9, span))
        entries.push({ start, end, text: caption })
        offset = end
      }
    }
    cursor += duration
  }

  const srt = entries
    .map((entry, index) => `${index + 1}\n${formatTime(entry.start)} --> ${formatTime(entry.end)}\n${entry.text}\n`)
    .join('\n')
  fs.writeFileSync(SRT, srt, 'utf8')
  console.log(`✓ 生成字幕 ${entries.length} 条，覆盖 ${formatTime(cursor)}`)

  // 注意：subtitles 滤镜对 Windows 盘符路径解析有坑，必须在 out 目录下用相对文件名
  const result = spawnSync(
    FFMPEG,
    [
      '-y', '-hide_banner', '-loglevel', 'error',
      '-i', path.basename(SOURCE),
      '-vf', `subtitles=${path.basename(SRT)}:force_style='${STYLE}'`,
      '-c:v', 'libx264', '-preset', 'veryfast', '-crf', '21',
      '-pix_fmt', 'yuv420p',
      '-c:a', 'copy', '-movflags', '+faststart',
      path.basename(TARGET),
    ],
    { cwd: OUT_ROOT, encoding: 'utf8' },
  )

  if (result.status !== 0) {
    console.error(result.stderr?.split('\n').slice(-10).join('\n'))
    throw new Error('烧录字幕失败')
  }

  const sizeMb = (fs.statSync(TARGET).size / 1024 / 1024).toFixed(1)
  const duration = probeDuration(TARGET)
  console.log(`✓ 成片（含字幕）：${TARGET}`)
  console.log(`  时长 ${Math.floor(duration / 60)} 分 ${Math.round(duration % 60)} 秒 · ${sizeMb} MB`)
}

main()
