$srt = Get-Content "$ws\tools\demo\out\subtitles.srt" -Raw -Encoding UTF8
# 统计落在 AI 协同段（约 132.2s ~ 266s）的字幕
$blocks = $srt -split "`r?`n`r?`n" | Where-Object { $_ -match '-->' }
$toSec = {
  param($t)
  $m = [regex]::Match($t, '(\d+):(\d+):(\d+),(\d+)')
  [double]$m.Groups[1].Value * 3600 + [double]$m.Groups[2].Value * 60 + [double]$m.Groups[3].Value + [double]$m.Groups[4].Value / 1000
}
$inAi = 0; $aiStart = $null; $aiEnd = $null
foreach ($b in $blocks) {
  $times = ([regex]::Matches($b, '\d+:\d+:\d+,\d+')).Value
  if ($times.Count -lt 2) { continue }
  $s = & $toSec $times[0]; $e = & $toSec $times[1]
  if ($s -ge 132 -and $e -le 267) { $inAi++; if (-not $aiStart) { $aiStart = $s }; $aiEnd = $e }
}
"字幕总条数: $($blocks.Count)"
"AI 协同段字幕条数: $inAi"
"AI 协同段范围: ${aiStart}s ~ ${aiEnd}s"
"AI 协同段时长: " + [math]::Round($aiEnd - $aiStart, 1) + " 秒（要求 ≥120 秒）"", "description": "Verify AI collaboration segment duration from subtitles", "timeoutMs": 120000}
